    gocpp::error rec::runContainsQueries(golistState* state, responseDeduper* response, gocpp::slice<gocpp::string> queries)
    {
        for(auto [gocpp_ignored, query] : queries)
        {
            // TODO(matloob): Do only one query per directory.
            auto fdir = filepath::Dir(query);
            // Pass absolute path of directory to go list so that it knows to treat it as a directory,
            // not a package path.
            auto [pattern, err] = filepath::Abs(fdir);
            if(err != nullptr)
            {
                return mocklib::Errorf("could not determine absolute path of file= query path %q: %v"_s, query, err);
            }
            packages::DriverResponse* dirResponse;
            std::tie(dirResponse, err) = rec::createDriverResponse(gocpp::recv(state), pattern);

            // If there was an error loading the package, or no packages are returned,
            // or the package is returned with errors, try to load the file as an
            // ad-hoc package.
            // Usually the error will appear in a returned package, but may not if we're
            // in module mode and the ad-hoc is located outside a module.
            if(err != nullptr || len(dirResponse->Packages) == 0 || len(dirResponse->Packages) == 1 && len(dirResponse->Packages[0]->GoFiles) == 0 &&
                        len(dirResponse->Packages[0]->Errors) == 1)
            {
                gocpp::error queryErr = {};
                if(std::tie(dirResponse, queryErr) = rec::adhocPackage(gocpp::recv(state), pattern, query); queryErr != nullptr)
                {
                    // return the original error
                    return err;
                }
            }
            auto isRoot = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, bool>>(), len(dirResponse->Roots));
            for(auto [gocpp_ignored, root] : dirResponse->Roots)
            {
                isRoot[root] = true;
            }
            for(auto [gocpp_ignored, pkg] : dirResponse->Packages)
            {
                // Add any new packages to the main set
                // We don't bother to filter packages that will be dropped by the changes of roots,
                // that will happen anyway during graph construction outside this function.
                // Over-reporting packages is not a problem.
                rec::addPackage(gocpp::recv(response), pkg);
                // if the package was not a root one, it cannot have the file
                if(! isRoot[pkg->ID])
                {
                    continue;
                }
                for(auto [gocpp_ignored, pkgFile] : pkg->GoFiles)
                {
                    if(filepath::Base(query) == filepath::Base(pkgFile))
                    {
                        rec::addRoot(gocpp::recv(response), pkg->ID);
                        break;
                    }
                }
            }
        }
        return nullptr;
    }

    // adhocPackage attempts to load or construct an ad-hoc package for a given
    // query, if the original call to the driver produced inadequate results.
    std::tuple<DriverResponse*, gocpp::error> rec::adhocPackage(golistState* state, gocpp::string pattern, gocpp::string query)
    {
        auto [response, err] = rec::createDriverResponse(gocpp::recv(state), query);
        if(err != nullptr)
        {
            return {nullptr, err};
        }
        // If we get nothing back from `go list`,
        // try to make this file into its own ad-hoc package.
        // TODO(rstambler): Should this check against the original response?
        if(len(response->Packages) == 0)
        {
            response->Packages = append(response->Packages, gocpp::InitPtr<Package>([=](auto& x) {
                x.ID = "command-line-arguments"_s;
                x.PkgPath = query;
                x.GoFiles = gocpp::slice<gocpp::string> {query};
                x.CompiledGoFiles = gocpp::slice<gocpp::string> {query};
                x.Imports = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, Package*>>());
            }));
            response->Roots = append(response->Roots, "command-line-arguments"_s);
        }
        // Handle special cases.
        if(len(response->Packages) == 1)
        {
            // golang/go#33482: If this is a file= query for ad-hoc packages where
            // the file only exists on an overlay, and exists outside of a module,
            // add the file to the package and remove the errors.
            if(response->Packages[0]->ID == "command-line-arguments"_s ||
                        filepath::ToSlash(response->Packages[0]->PkgPath) == filepath::ToSlash(query))
            {
                if(len(response->Packages[0]->GoFiles) == 0)
                {
                    // avoid recomputing abspath
                    auto filename = filepath::Join(pattern, filepath::Base(query));
                    // TODO(matloob): check if the file is outside of a root dir?
                    for(auto [path, gocpp_ignored] : state->cfg->Overlay)
                    {
                        if(path == filename)
                        {
                            response->Packages[0]->Errors = nullptr;
                            response->Packages[0]->GoFiles = gocpp::slice<gocpp::string> {path};
                            response->Packages[0]->CompiledGoFiles = gocpp::slice<gocpp::string> {path};
                        }
                    }
                }
            }
        }
        return {response, nullptr};
    }

